type Material = { id: string; name: string; type: string; size: string; status: "indexed" | "queued" | "needs_review"; addedAt: string; text?: string; duration?: number };
type Subject = { id: string; name: string; color: string; mastery: number; examDate?: string; topics: Topic[]; materials: Material[]; minutes: number };
type Session = { id: string; subjectId: string; topicId: string; duration: number; elapsed: number; status: "active" | "paused"; startedAt: string };
type Workspace = { subjects: Subject[]; session?: Session; savedItems: Array<{ id: string; title: string; subject: string; source: string }>; streak: number; minutesToday: number; dailyGoal: number };

type View = "dashboard" | "subjects" | "plan" | "review" | "progress" | "saved" | "settings";

