function readWorkspace(key: string): Workspace {
  try {
    const raw = localStorage.getItem(key);
    if (raw) return JSON.parse(raw) as Workspace;
  } catch {}
  return starterWorkspace;
}

function useWorkspace(userId?: string) {
  const key = `studynivo-workspace-${userId ?? "preview"}`;
  const [workspace, setWorkspace] = useState<Workspace>(() => readWorkspace(key));
  const [loadedKey, setLoadedKey] = useState(key);
  const subjectsQuery = trpc.workspace.subjects.useQuery(undefined, { enabled: Boolean(userId), retry: false, refetchOnWindowFocus: false });
  useEffect(() => {
    if (loadedKey === key) return;
    setWorkspace(readWorkspace(key));
    setLoadedKey(key);
  }, [key, loadedKey]);
  useEffect(() => {
    if (!subjectsQuery.data?.length) return;
    setWorkspace((current) => ({ ...current, subjects: subjectsQuery.data.map((serverSubject) => {
      const existing = current.subjects.find((item) => item.id === String(serverSubject.id));
      return { id: String(serverSubject.id), name: serverSubject.name, color: serverSubject.color, mastery: serverSubject.mastery, examDate: serverSubject.examDate ? String(serverSubject.examDate).slice(0, 10) : existing?.examDate, minutes: serverSubject.minutesStudied, topics: existing?.topics ?? [], materials: existing?.materials ?? [] };
    }) }));
  }, [subjectsQuery.data]);
  useEffect(() => {
    if (loadedKey === key) localStorage.setItem(key, JSON.stringify(workspace));
  }, [key, loadedKey, workspace]);
  return [workspace, setWorkspace] as const;
}

function initials(name?: string | null) {
  return (name || "StudyNivo").split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase();
}

function formatExam(date?: string) { return formatExamText(date); }
function formatAudioDuration(seconds?: number) { if (!seconds || seconds < 1) return undefined; return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`; }

function Logo({ compact = false }: { compact?: boolean }) {
  return <div className="flex items-center gap-2.5"><span className="brand-mark"><span className="text-[17px] font-black">N</span></span>{!compact && <span className="text-[15px] font-extrabold tracking-[-.04em] text-[#172b34]">{trStatic("StudyNivo")}</span>}</div>;
}

