function AppShell({ locale, onLocale, workspace, setWorkspace, user, logout }: { locale: Locale; onLocale: (locale: Locale) => void; workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; user: { name?: string | null; email?: string | null } | null; logout: () => Promise<void> }) {
  const [location, setLocation] = useLocation();
  const currentView: View = location.startsWith("/subjects") ? "subjects" : location.startsWith("/study-plan") ? "plan" : location.startsWith("/review") ? "review" : location.startsWith("/progress") ? "progress" : location.startsWith("/saved") ? "saved" : location.startsWith("/settings") ? "settings" : "dashboard";
  const go = (view: View) => setLocation(view === "dashboard" ? "/dashboard" : `/${view === "plan" ? "study-plan" : view}`);
  const subjectMatch = location.match(/^\/subjects\/([^/]+)/);
  const sessionMatch = location.match(/^\/session\/([^/]+)/);
  const practiceMatch = location.match(/^\/practice\/([^/]+)/);
  const activeSubject = subjectMatch ? workspace.subjects.find((subject) => subject.id === subjectMatch[1]) : undefined;
  const isKnownLocation = ["/", "/dashboard", "/subjects", "/study-plan", "/review", "/progress", "/saved", "/settings"].includes(location) || Boolean(activeSubject) || Boolean(sessionMatch) || Boolean(practiceMatch);
  return <div className="app-shell" dir={getDirection(locale)}>
    <aside className="app-sidebar"><div className="px-2"><Logo /></div><div className="mt-10 px-2"><div className="kicker mb-3">{trStatic("Study command center")}</div><div className="rounded-2xl bg-[#eaf4f1] p-3"><div className="flex items-start justify-between"><span className="text-xs font-extrabold text-[#205d56]">{trStatic("Today’s focus")}</span><Zap className="size-4 text-[#0f766e]" /></div><div className="mt-2 text-[11px] leading-5 text-[#4e7b74]">{trStatic("One clear task beats ten open tabs.")}</div></div></div><nav className="mt-7 flex flex-1 flex-col gap-1">{navItems.map((item) => <button key={item.id} className={`nav-item ${currentView === item.id ? "active" : ""}`} onClick={() => go(item.id)}><item.icon className="size-[17px]" /><span>{trStatic(item.label)}</span></button>)}<button className={`nav-item ${currentView === "settings" ? "active" : ""} mt-5`} onClick={() => go("settings")}><Settings2 className="size-[17px]" /><span>{trStatic("Settings")}</span></button></nav><div className="border-t border-[#e5ece8] pt-4"><div className="flex items-center gap-2.5 px-2"><div className="grid size-8 place-items-center rounded-full bg-[#d7ece7] text-[11px] font-extrabold text-[#0f766e]">{initials(user?.name)}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-extrabold text-[#34464d]">{user?.name || "Student"}</div><div className="truncate text-[10px] text-[#8b9899]">{user?.email || "Personal workspace"}</div></div><button aria-label="Sign out" className="text-[#9aa6a7] hover:text-[#0f766e]" onClick={() => void logout()}><LogOut className="size-4" /></button></div></div></aside>
    <main className="app-main"><div className="content-wrap">{!isKnownLocation ? <NotFoundView onNavigate={setLocation} /> : sessionMatch ? <StudySession sessionId={sessionMatch[1]} workspace={workspace} setWorkspace={setWorkspace} onNavigate={setLocation} /> : practiceMatch ? <PersistedPracticeTest subjectId={practiceMatch[1]} onExit={() => setLocation(`/subjects/${practiceMatch[1]}`)} /> : activeSubject ? <SubjectSpace subject={activeSubject} workspace={workspace} setWorkspace={setWorkspace} onNavigate={setLocation} locale={locale} /> : currentView === "dashboard" ? <Dashboard workspace={workspace} setWorkspace={setWorkspace} onNavigate={setLocation} /> : currentView === "subjects" ? <Subjects workspace={workspace} setWorkspace={setWorkspace} onNavigate={setLocation} /> : currentView === "plan" ? <StudyPlan workspace={workspace} onNavigate={setLocation} /> : currentView === "review" ? <ReviewQueue /> : currentView === "progress" ? <ProgressView workspace={workspace} /> : currentView === "saved" ? <SavedItems workspace={workspace} setWorkspace={setWorkspace} /> : <Settings locale={locale} onLocale={onLocale} />}</div></main>
    <div className="mobile-nav">{[navItems[0], navItems[1], navItems[2], navItems[4], { id: "settings" as View, label: "More", icon: Menu }].map((item) => <button key={item.id} className={currentView === item.id ? "active" : ""} onClick={() => go(item.id)}><item.icon className="size-[17px]" /><span>{trStatic(item.label)}</span></button>)}</div>
  </div>;
}

function Dashboard({ workspace, setWorkspace, onNavigate }: { workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void }) {
  const hour = new Date().getHours();
  const greeting = hour < 12 ? "Good morning" : hour < 18 ? "Good afternoon" : "Good evening";
  const next = useMemo(() => [...workspace.subjects].sort((a, b) => a.mastery - b.mastery)[0] ?? workspace.subjects[0], [workspace.subjects]);
  const topic = next?.topics.find((item) => item.weak) ?? next?.topics[0];
  const startSession = () => { if (!next || !topic) return; const id = `session-${Date.now()}`; setWorkspace((prev) => ({ ...prev, session: { id, subjectId: next.id, topicId: topic.id, duration: 30, elapsed: 0, status: "active", startedAt: new Date().toISOString() } })); onNavigate(`/session/${id}`); };
  return <><div className="flex flex-wrap items-end justify-between gap-5"><div><div className="eyebrow">{trStatic("Tuesday · October 1")}</div><h1 className="page-title">{greeting}, student.</h1><p className="page-subtitle">{trStatic("Your study path is ready. Start with the one task that will move you forward.")}</p></div><button className="btn-light" onClick={() => onNavigate("/subjects")}><Plus className="size-4" />{trStatic("Add subject")}</button></div>
    <div className="grid-dashboard mt-8"><div className="next-card p-6 md:p-7"><div className="relative z-10"><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="flex items-center gap-2 text-xs font-bold text-[#bde8df]"><Sparkles className="size-4" />{trStatic("Your next best study step")}</div><h2 className="mt-5 text-[29px] font-extrabold tracking-[-.055em]">{next?.name ?? "Create your first subject"} <span className="text-[#a9dcd3]">—</span> {topic?.name ?? "Upload your notes"}</h2><p className="mt-3 max-w-[470px] text-sm leading-6 text-[#d5f0eb]">{topic?.note ?? "Add a source and StudyNivo will build a focused next step."}</p></div><div className="rounded-2xl border border-white/20 bg-white/10 px-3 py-2 text-right"><div className="text-[10px] font-bold uppercase tracking-[.12em] text-[#bde8df]">{trStatic("Recommended")}</div><div className="mt-1 text-xl font-extrabold">30 min</div></div></div><div className="mt-7 flex flex-wrap items-center gap-2"><span className="source-pill border border-white/15 bg-white/10 text-[#d5f0eb]">{next?.examDate ? formatExam(next.examDate) : "Build your study map"}</span><span className="source-pill border border-white/15 bg-white/10 text-[#d5f0eb]">{topic?.weak ? "Weak topic" : "Keep momentum"}</span>{topic?.source && <span className="source-pill border border-white/15 bg-white/10 text-[#d5f0eb]">{topic.source}</span>}</div><div className="mt-8 flex flex-wrap items-center gap-3"><button className="rounded-xl bg-white px-4 py-3 text-xs font-extrabold text-[#0f766e] shadow-sm" onClick={startSession}><Play className="mr-1.5 inline size-4" />{trStatic("Start studying")}</button><button className="rounded-xl border border-white/20 px-4 py-3 text-xs font-bold text-white hover:bg-white/10" onClick={() => next && onNavigate(`/subjects/${next.id}`)}>{trStatic("Open subject")}<ArrowRight className="ml-1.5 inline size-3.5" /></button></div></div></div><div className="card overflow-hidden p-0"><ProfileIllustration /><div className="p-6"><div className="flex items-start justify-between gap-4"><div><div className="kicker">{trStatic("Your rhythm")}</div><h3 className="mt-2 text-lg font-extrabold tracking-[-.03em]">{trStatic("Small wins, compounding.")}</h3></div><div className="grid size-10 shrink-0 place-items-center rounded-full bg-[#eaf4f1] text-[#0f766e]"><Target className="size-5" /></div></div><div className="mt-6 flex items-end justify-between"><div><div className="text-4xl font-extrabold tracking-[-.06em]">{workspace.minutesToday}<span className="ml-1 text-base font-bold text-[#92a09f]">{trStatic("min")}</span></div><div className="mt-1 text-xs font-semibold text-[#879497]">of {workspace.dailyGoal} min today</div></div><div className="text-right text-xs font-extrabold text-[#0f766e]">{Math.round(Math.min(100, (workspace.minutesToday / workspace.dailyGoal) * 100))}%</div></div><div className="progress-track mt-4"><div className="progress-fill" style={{ width: `${Math.min(100, (workspace.minutesToday / workspace.dailyGoal) * 100)}%` }} /></div><div className="mt-5 flex items-center justify-between text-xs"><span className="font-semibold text-[#829092]">{workspace.streak} day study streak</span><span className="font-extrabold text-[#0f766e]">{trStatic("Keep going")}</span></div></div></div></div>
    <div className="grid-metrics mt-5"><Metric icon={<Target />} label="Today's goal" value={`${workspace.minutesToday}/${workspace.dailyGoal} min`} note="A realistic pace" /><Metric icon={<Zap />} label="Study streak" value={`${workspace.streak} days`} note="Consistency matters" /><Metric icon={<BarChart3 />} label="Overall progress" value={`${Math.round(workspace.subjects.reduce((sum, item) => sum + item.mastery, 0) / Math.max(1, workspace.subjects.length))}%`} note={`${workspace.subjects.length} study spaces`} /><Metric icon={<CalendarDays />} label="Upcoming exams" value={`${workspace.subjects.filter((item) => item.examDate).length}`} note="Dates shape priority" /></div>
    {workspace.session && <div className="card mt-5 flex flex-wrap items-center justify-between gap-4 p-5"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-[#fff5df] text-[#bb7b1d]"><Pause className="size-4" /></div><div><div className="text-xs font-extrabold text-[#34474d]">{trStatic("Unfinished study session")}</div><div className="mt-1 text-xs text-[#849295]">{workspace.subjects.find((item) => item.id === workspace.session?.subjectId)?.name} · Continue where you paused</div></div></div><button className="btn-light" onClick={() => onNavigate(`/session/${workspace.session?.id}`)}>{trStatic("Continue session")}<ArrowRight className="size-4" /></button></div>}
    <div className="mt-8 flex items-end justify-between"><div><div className="kicker">{trStatic("Your study spaces")}</div><h2 className="mt-2 text-xl font-extrabold tracking-[-.04em]">{trStatic("Keep your subjects close.")}</h2></div><button className="btn-quiet" onClick={() => onNavigate("/subjects")}>{trStatic("View all")}<ChevronRight className="size-4" /></button></div><div className="grid-subjects mt-4">{workspace.subjects.slice(0, 2).map((subject) => <SubjectCard key={subject.id} subject={subject} onClick={() => onNavigate(`/subjects/${subject.id}`)} />)}</div>
  </>;
}

function Metric({ icon, label, value, note }: { icon: React.ReactNode; label: string; value: string; note: string }) { return <div className="card metric-card"><div className="flex items-center justify-between"><span className="metric-label">{trStatic(label)}</span><span className="text-[#0f766e]">{icon}</span></div><div className="metric-value">{value}</div><div className="metric-note">{trStatic(note)}</div></div>; }
function SubjectCard({ subject, onClick }: { subject: Subject; onClick: () => void }) { return <button className="card group p-5 text-left transition hover:-translate-y-0.5 hover:border-[#acd1c8]" onClick={onClick}><div className="flex items-start justify-between"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl text-white" style={{ background: subject.color }}><FlaskConical className="size-5" /></div><div><div className="text-sm font-extrabold text-[#34474d]">{subject.name}</div><div className="mt-1 text-[11px] font-semibold text-[#8a9698]">{subject.topics.length} topics · {subject.materials.length} sources</div></div></div><ChevronRight className="size-4 text-[#9aa6a7] transition group-hover:translate-x-1 group-hover:text-[#0f766e]" /></div><div className="mt-5 flex items-center justify-between text-xs"><span className="font-bold text-[#748286]">{trStatic("Mastery")}</span><span className="font-extrabold text-[#0f766e]">{subject.mastery}%</span></div><div className="progress-track mt-2"><div className="progress-fill" style={{ width: `${subject.mastery}%`, background: subject.color }} /></div><div className="mt-4 flex items-center justify-between text-[11px] font-semibold text-[#8a9799]"><span>{subject.examDate ? formatExam(subject.examDate) : "No exam date yet"}</span><span>{subject.minutes} min studied</span></div></button>; }

function Subjects({ workspace, setWorkspace, onNavigate }: { workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(""); const [examDate, setExamDate] = useState("");
  const createSubjectMutation = trpc.workspace.createSubject.useMutation();
  const utils = trpc.useUtils();
  const create = () => { if (!name.trim()) return; const id = name.toLowerCase().replace(/[^a-z0-9]+/g, "-") || `subject-${Date.now()}`; void createSubjectMutation.mutateAsync({ name: name.trim(), examDate: examDate || undefined }).then(() => utils.workspace.subjects.invalidate()).catch((error) => console.error("[StudyNivo] subject sync failed", error)); setWorkspace((prev) => ({ ...prev, subjects: [...prev.subjects, { id, name: name.trim(), color: "#6b8e82", mastery: 0, examDate: examDate || undefined, minutes: 0, topics: [], materials: [] }] })); setName(""); setExamDate(""); setOpen(false); };
  return <><div className="flex flex-wrap items-end justify-between gap-5"><div><div className="eyebrow">{trStatic("Study spaces")}</div><h1 className="page-title">{trStatic("Your subjects.")}</h1><p className="page-subtitle">{trStatic("Each space keeps its own sources, topics, practice, and progress.")}</p></div><button className="btn-primary" onClick={() => setOpen(true)}><Plus className="size-4" />{trStatic("Create subject")}</button></div><div className="mt-8 grid-subjects">{workspace.subjects.map((subject) => <SubjectCard key={subject.id} subject={subject} onClick={() => onNavigate(`/subjects/${subject.id}`)} />)}<button className="card flex min-h-[205px] flex-col items-center justify-center border-dashed p-5 text-center transition hover:border-[#8ac0b5]" onClick={() => setOpen(true)}><div className="grid size-11 place-items-center rounded-full bg-[#eaf4f1] text-[#0f766e]"><Plus className="size-5" /></div><div className="mt-4 text-sm font-extrabold">{trStatic("Add another study space")}</div><div className="mt-1 text-xs text-[#899699]">{trStatic("Start with a name. Details can come later.")}</div></button></div>{open && <div className="overlay"><div className="modal"><div className="flex items-start justify-between"><div><div className="eyebrow">{trStatic("New study space")}</div><h2 className="mt-2 text-2xl font-extrabold tracking-[-.04em]">{trStatic("What are you studying?")}</h2><p className="mt-2 text-xs leading-5 text-[#7c8a8d]">{trStatic("You can add exam dates, sources, and topics after this quick start.")}</p></div><button className="btn-quiet" onClick={() => setOpen(false)}><X className="size-4" /></button></div><div className="mt-6 space-y-4"><label className="block"><span className="kicker">{trStatic("Subject name")}</span><input autoFocus className="input mt-2" placeholder="e.g. Physics" value={name} onChange={(event) => setName(event.target.value)} /></label><label className="block"><span className="kicker">{trStatic("Exam date")}<span className="normal-case tracking-normal text-[#a3aeae]">(optional)</span></span><input type="date" className="input mt-2" value={examDate} onChange={(event) => setExamDate(event.target.value)} /></label></div><div className="mt-7 flex justify-end gap-2"><button className="btn-light" onClick={() => setOpen(false)}>{trStatic("Cancel")}</button><button className="btn-primary" onClick={create}>{trStatic("Create subject")}<ArrowRight className="size-4" /></button></div></div></div>}</>;
}

function SubjectSpace({ subject, workspace, setWorkspace, onNavigate, locale }: { subject: Subject; workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void; locale: Locale }) {
  const [tab, setTab] = useState<"overview" | "materials" | "topics" | "study" | "practice" | "flashcards" | "chat" | "progress">("overview");
  const [note, setNote] = useState(""); const [chatInput, setChatInput] = useState(""); const [chatAnswer, setChatAnswer] = useState(""); const [flashIndex, setFlashIndex] = useState(0); const [flipped, setFlipped] = useState(false);
  const askMaterialMutation = trpc.ai.askTextMaterial.useMutation();
  const addTextMaterialMutation = trpc.workspace.addTextMaterial.useMutation();
  const uploadMaterialMutation = trpc.workspace.uploadMaterial.useMutation();
  const serverSubjectQuery = trpc.workspace.subject.useQuery({ id: Number(subject.id) }, { enabled: /^\d+$/.test(subject.id), refetchInterval: 3000, retry: false });
  useEffect(() => {
    const serverSubject = serverSubjectQuery.data;
    if (!serverSubject) return;
    setWorkspace((prev) => ({ ...prev, subjects: prev.subjects.map((item) => item.id === subject.id ? { ...item, materials: serverSubject.materials.map((material) => ({ id: String(material.id), name: material.name, type: material.kind.toUpperCase(), size: material.sizeBytes ? `${Math.max(1, Math.round(material.sizeBytes / 1024))} KB` : "Processing", status: material.status === "failed" ? "needs_review" : material.status === "needs_review" ? "needs_review" : material.status === "indexed" ? "indexed" : "queued", addedAt: material.createdAt ? new Date(material.createdAt).toLocaleDateString() : "Just now", text: material.textContent ?? undefined, duration: material.audioDurationSeconds ?? undefined })) } : item) }));
  }, [serverSubjectQuery.data, subject.id, setWorkspace]);
  const weakTopic = subject.topics.find((item) => item.weak) ?? subject.topics[0];
  const startSession = () => { if (!weakTopic) return; const id = `session-${Date.now()}`; setWorkspace((prev) => ({ ...prev, session: { id, subjectId: subject.id, topicId: weakTopic.id, duration: 30, elapsed: 0, status: "active", startedAt: new Date().toISOString() } })); onNavigate(`/session/${id}`); };
  const addNote = () => { if (!note.trim()) return; const material: Material = { id: `note-${Date.now()}`, name: "Pasted study notes", type: "Notes", size: `${note.length} chars`, status: "indexed", addedAt: "Just now", text: note }; if (/^\d+$/.test(subject.id)) void addTextMaterialMutation.mutateAsync({ subjectId: Number(subject.id), name: material.name, kind: "notes", textContent: note, sourceRef: "Pasted study notes" }).catch((error) => console.error("[StudyNivo] material sync failed", error)); setWorkspace((prev) => ({ ...prev, subjects: prev.subjects.map((item) => item.id === subject.id ? { ...item, materials: [material, ...item.materials] } : item) })); setNote(""); };
  const addFile = async (file?: File) => {
    if (!file) return;
    const isText = /\.txt$|\.md$|text\//i.test(file.name) || file.type === "text/plain" || file.type === "text/markdown";
    const isDocument = /\.pdf$|\.docx$|\.png$|\.jpe?g$|\.webp$/i.test(file.name) || /^(application\/pdf|application\/vnd\.openxmlformats-officedocument\.wordprocessingml\.document|image\/)/i.test(file.type);
    const isAudio = /\.(mp3|wav|ogg|m4a|webm)$/i.test(file.name) || /^audio\//i.test(file.type);
    const maxBytes = isAudio ? 50 * 1024 * 1024 : 20 * 1024 * 1024;
    if (!isText && !isDocument && !isAudio) { setChatAnswer(trStatic("Use PDF, DOCX, images, audio, TXT, or Markdown.")); return; }
    if (file.size > maxBytes) { setChatAnswer(trStatic("This file is larger than the 20 MB document / 50 MB audio limit.")); return; }
    const material: Material = { id: `file-${Date.now()}`, name: file.name, type: file.name.split(".").pop()?.toUpperCase() || "FILE", size: `${Math.max(1, Math.round(file.size / 1024))} KB`, status: isText ? "indexed" : "queued", addedAt: "Just now" };
    const reader = new FileReader();
    reader.onload = async () => {
      const value = String(reader.result ?? "");
      if ((isDocument || isAudio) && /^\d+$/.test(subject.id)) {
        const lowerName = file.name.toLowerCase();
        const mimeType = isAudio ? (file.type || (lowerName.endsWith(".mp3") ? "audio/mpeg" : lowerName.endsWith(".wav") ? "audio/wav" : lowerName.endsWith(".ogg") ? "audio/ogg" : lowerName.endsWith(".m4a") ? "audio/mp4" : "audio/webm")) : lowerName.endsWith(".pdf") ? "application/pdf" : lowerName.endsWith(".png") ? "image/png" : lowerName.endsWith(".webp") ? "image/webp" : lowerName.endsWith(".jpg") || lowerName.endsWith(".jpeg") ? "image/jpeg" : "application/vnd.openxmlformats-officedocument.wordprocessingml.document";
        try { await uploadMaterialMutation.mutateAsync({ subjectId: Number(subject.id), name: file.name, mimeType: mimeType as "application/pdf" | "application/vnd.openxmlformats-officedocument.wordprocessingml.document" | "image/png" | "image/jpeg" | "image/webp" | "audio/mpeg" | "audio/wav" | "audio/ogg" | "audio/mp4" | "audio/webm", base64: value }); }
        catch (error) { console.error("[StudyNivo] material upload failed", error); setChatAnswer(trStatic("Upload failed. Check the file type and try again.")); return; }
      } else if (isText && /^\d+$/.test(subject.id)) {
        await addTextMaterialMutation.mutateAsync({ subjectId: Number(subject.id), name: file.name, kind: "text", textContent: value, sourceRef: file.name }).catch((error) => console.error("[StudyNivo] file sync failed", error));
      }
      setWorkspace((prev) => ({ ...prev, subjects: prev.subjects.map((item) => item.id === subject.id ? { ...item, materials: [{ ...material, text: isText ? value : undefined }, ...item.materials] } : item) }));
    };
    if (isText) reader.readAsText(file); else reader.readAsDataURL(file);
  };
  const ask = async () => { const q = chatInput.trim(); if (!q) return; const context = subject.materials.map((material) => material.text).filter(Boolean).join("\n\n"); if (!context) { setChatAnswer(`Add a text or Markdown source to ${subject.name} first. I won't guess beyond the material you provide.`); return; } try { const result = await askMaterialMutation.mutateAsync({ subjectName: subject.name, question: q, context, sourceRef: subject.materials[0]?.name, locale }); setChatAnswer(result.answer); } catch (error) { console.error("[StudyNivo] grounded chat failed", error); setChatAnswer("I couldn't reach the grounded coach right now. Try again when the AI service is available."); } setChatInput(""); };
  const flashcard = subject.topics[flashIndex % Math.max(1, subject.topics.length)];
  const tabs = [{ id: "overview", label: "Overview" }, { id: "materials", label: "Materials" }, { id: "topics", label: "Topics" }, { id: "study", label: "Study" }, { id: "practice", label: "Practice" }, { id: "flashcards", label: "Flashcards" }, { id: "chat", label: "Ask material" }, { id: "progress", label: "Progress" }] as const;
  return <><button className="btn-quiet -ml-2 mb-5" onClick={() => onNavigate("/subjects")}><ArrowRight className="size-4 rotate-180" />{trStatic("All subjects")}</button><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">{trStatic("Subject study space")}</div><h1 className="page-title">{subject.name}</h1><p className="page-subtitle">{trStatic("Everything here is grounded in this subject’s sources.")}</p></div><div className="flex items-center gap-2"><span className="source-pill"><Target className="size-3.5 text-[#0f766e]" /> {subject.mastery}% mastery</span>{subject.examDate && <span className="source-pill"><CalendarDays className="size-3.5 text-[#0f766e]" /> {formatExam(subject.examDate)}</span>}</div></div><div className="mt-7 flex gap-1 overflow-x-auto border-b border-[#e1e9e5] pb-2">{tabs.map((item) => <button key={item.id} className={`tab ${tab === item.id ? "active" : ""}`} onClick={() => setTab(item.id)}>{item.label}</button>)}</div>{tab === "overview" && <SubjectOverview subject={subject} onStart={startSession} onTab={setTab} />}{tab === "materials" && <MaterialsTab subject={subject} note={note} setNote={setNote} onAddNote={addNote} onFile={addFile} />}{tab === "topics" && <TopicsTab subject={subject} onStart={startSession} />}{tab === "study" && <StudyTab subject={subject} onStart={startSession} onTab={setTab} />}{tab === "practice" && <PracticeTab subject={subject} onPractice={() => onNavigate(`/practice/${subject.id}`)} />}{tab === "flashcards" && <FlashcardsReview subjectId={subject.id} subjectName={subject.name} />}{tab === "chat" && <div className="mt-6 grid max-w-3xl gap-4"><div className="card p-6"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-[#eaf4f1] text-[#0f766e]"><MessageCircle className="size-5" /></div><div><div className="kicker">{trStatic("Ask your material")}</div><h2 className="mt-1 text-xl font-extrabold">{trStatic("A grounded coach for")} {subject.name}</h2></div></div><p className="mt-4 text-sm leading-6 text-[#748287]">{trStatic("Ask about a topic, what to memorize, or where something was explained. Answers stay inside this subject space.")}</p><div className="mt-5 flex gap-2"><input className="input" value={chatInput} onChange={(event) => setChatInput(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") ask(); }} placeholder={trStatic("e.g. Explain genetics simply")} /><button className="btn-primary shrink-0" onClick={ask}>{trStatic("Ask")}<ArrowRight className="size-4" /></button></div>{chatAnswer && <div className="mt-5 rounded-2xl border border-[#dcece7] bg-[#f1f8f5] p-4 text-sm leading-7 text-[#365b54]"><div className="mb-2 flex items-center gap-2 text-xs font-extrabold text-[#0f766e]"><ShieldCheckIcon />{trStatic("Grounded answer")}</div>{chatAnswer}</div>}</div></div>}{tab === "progress" && <ProgressSubject subject={subject} />}</>;
}

function SubjectOverview({ subject, onStart, onTab }: { subject: Subject; onStart: () => void; onTab: (tab: "materials" | "topics" | "practice" | "chat") => void }) { return <div className="mt-6 grid-dashboard"><div className="card p-6"><div className="flex items-start justify-between"><div><div className="kicker">{trStatic("Your next move")}</div><h2 className="mt-2 text-2xl font-extrabold tracking-[-.05em]">{trStatic("Strengthen")} {subject.topics.find((item) => item.weak)?.name ?? trStatic("your first topic")}</h2><p className="mt-3 max-w-lg text-sm leading-6 text-[#748287]">{trStatic("The next session uses your weakest topic and the sources already inside this subject.")}</p></div><div className="grid size-11 place-items-center rounded-2xl bg-[#eaf4f1] text-[#0f766e]"><Sparkles className="size-5" /></div></div><div className="mt-6 flex flex-wrap gap-2"><span className="topic-chip"><Clock3 className="size-3.5" />{trStatic("30 min")}</span><span className="topic-chip"><Lightbulb className="size-3.5" />{trStatic("Low confidence review")}</span></div><button className="btn-primary mt-7" onClick={onStart}><Play className="size-4" />{trStatic("Start session")}</button></div><div className="card p-6"><div className="kicker">{trStatic("Space at a glance")}</div><div className="mt-5 grid grid-cols-2 gap-3"><button className="soft-card p-4 text-left" onClick={() => onTab("materials")}><FileText className="size-5 text-[#0f766e]" /><div className="mt-3 text-xl font-extrabold">{subject.materials.length}</div><div className="mt-1 text-xs font-semibold text-[#849195]">{trStatic("Sources")}</div></button><button className="soft-card p-4 text-left" onClick={() => onTab("topics")}><Brain className="size-5 text-[#0f766e]" /><div className="mt-3 text-xl font-extrabold">{subject.topics.length}</div><div className="mt-1 text-xs font-semibold text-[#849195]">{trStatic("Topics")}</div></button><button className="soft-card p-4 text-left" onClick={() => onTab("practice")}><ListChecks className="size-5 text-[#0f766e]" /><div className="mt-3 text-xl font-extrabold">{trStatic("Practice")}</div><div className="mt-1 text-xs font-semibold text-[#849195]">{trStatic("Test your recall")}</div></button><button className="soft-card p-4 text-left" onClick={() => onTab("chat")}><MessageCircle className="size-5 text-[#0f766e]" /><div className="mt-3 text-xl font-extrabold">{trStatic("Ask")}</div><div className="mt-1 text-xs font-semibold text-[#849195]">{trStatic("Your material")}</div></button></div></div><div className="card p-6 md:col-span-2"><div className="flex items-center justify-between"><div><div className="kicker">{trStatic("Topic map")}</div><h2 className="mt-2 text-xl font-extrabold">{trStatic("Where your attention goes next")}</h2></div><span className="topic-chip">{subject.mastery}% overall</span></div><div className="mt-5 grid gap-3 md:grid-cols-3">{subject.topics.map((topic) => <TopicRow key={topic.id} topic={topic} />)}</div></div></div>; }
function TopicRow({ topic }: { topic: Topic }) { return <div className="rounded-2xl border border-[#e5ece8] p-4"><div className="flex items-start justify-between gap-3"><div><div className="text-sm font-extrabold text-[#34474d]">{topic.name}</div><div className="mt-1 text-[11px] leading-5 text-[#849194]">{topic.note}</div></div>{topic.weak && <CircleAlert className="size-4 shrink-0 text-[#c18a37]" />}</div><div className="mt-4 flex items-center gap-2"><div className="progress-track"><div className="progress-fill" style={{ width: `${topic.mastery}%` }} /></div><span className="text-xs font-extrabold text-[#0f766e]">{topic.mastery}%</span></div><div className="mt-3 text-[10px] font-semibold text-[#97a2a2]">{topic.source}</div></div>; }

function MaterialsTab({ subject, note, setNote, onAddNote, onFile }: { subject: Subject; note: string; setNote: (value: string) => void; onAddNote: () => void; onFile: (file?: File) => void }) { const retryMaterialMutation = trpc.workspace.retryMaterial.useMutation(); const analyzeMaterialMutation = trpc.workspace.analyzeMaterial.useMutation(); return <div className="mt-6 grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="card p-6"><div className="kicker">{trStatic("Add a source")}</div><h2 className="mt-2 text-xl font-extrabold">{trStatic("Bring your material in.")}</h2><p className="mt-2 text-xs leading-5 text-[#849194]">{trStatic("Paste notes now or queue a document. Text notes are indexed immediately; larger files stay visible with a clear processing state.")}</p><textarea className="textarea mt-5" value={note} onChange={(event) => setNote(event.target.value)} placeholder="Paste a lecture, notes, or a key passage…" /><button className="btn-primary mt-3 w-full" onClick={onAddNote}><Plus className="size-4" />{trStatic("Add notes")}</button><label className="mt-3 flex min-h-[94px] cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed border-[#b9d7ce] bg-[#f7fbf9] text-center"><Upload className="size-5 text-[#0f766e]" /><span className="mt-2 text-xs font-extrabold text-[#48615e]">{trStatic("Upload PDF, DOCX, images, audio, TXT, or Markdown")}</span><span className="mt-1 text-[10px] text-[#8e9c9c]">{trStatic("Audio is transcribed with timestamps before indexing.")}</span><input className="hidden" type="file" accept=".pdf,.docx,.png,.jpg,.jpeg,.webp,.mp3,.wav,.ogg,.m4a,.webm,.txt,.md,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document,image/png,image/jpeg,image/webp,audio/mpeg,audio/wav,audio/ogg,audio/mp4,audio/webm,text/plain,text/markdown" onChange={(event) => onFile(event.target.files?.[0])} /></label></div><div className="card p-6"><div className="flex items-center justify-between"><div><div className="kicker">{trStatic("Source index")}</div><h2 className="mt-2 text-xl font-extrabold">{subject.materials.length} {trStatic("sources in")} {subject.name}</h2></div><Search className="size-5 text-[#92a09f]" /></div><div className="mt-5 space-y-2">{subject.materials.map((material) => <div key={material.id} className="flex items-center gap-3 rounded-2xl border border-[#e5ece8] p-4"><div className="grid size-10 place-items-center rounded-xl bg-[#eef6f3] text-[#0f766e]"><FileText className="size-5" /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-extrabold text-[#3c4e54]">{material.name}</div><div className="mt-1 flex flex-wrap gap-2 text-[10px] font-semibold text-[#8c999b]"><span>{material.type}</span><span>·</span><span>{material.size}</span><span>·</span><span>{material.duration ? formatAudioDuration(material.duration) : material.addedAt}</span></div></div>{material.status === "needs_review" ? <button className="source-pill text-[#b87920]" onClick={() => { if (/^\d+$/.test(material.id)) void retryMaterialMutation.mutateAsync({ materialId: Number(material.id) }); }}> <RotateCcw className="size-3.5" />{trStatic("Retry")}</button> : material.status === "indexed" && /^\d+$/.test(material.id) ? <button className="source-pill text-[#32806c]" onClick={() => void analyzeMaterialMutation.mutateAsync({ subjectId: Number(subject.id), materialId: Number(material.id) })}>{trStatic("Analyze topics")}</button> : <span className={`source-pill ${material.status === "queued" ? "text-[#8c7b58]" : "text-[#32806c]"}`}>{material.status === "indexed" ? <><CircleCheck className="size-3.5" />{trStatic("Indexed")}</> : <><Clock3 className="size-3.5" />{trStatic("Processing")}</>}</span>}</div>)}</div><MaterialSearch subjectId={subject.id} subjectName={subject.name} /></div></div>; }
function TopicsTab({ subject, onStart }: { subject: Subject; onStart: () => void }) { return <div className="mt-6"><div className="card p-6"><div className="flex flex-wrap items-center justify-between gap-4"><div><div className="kicker">{trStatic("Topic map")}</div><h2 className="mt-2 text-xl font-extrabold">{trStatic("What your material contains")}</h2><p className="mt-2 text-sm text-[#77868a]">{trStatic("Topics are the building blocks behind your summaries, questions, and next sessions.")}</p></div><button className="btn-light" onClick={onStart}><Play className="size-4 text-[#0f766e]" />{trStatic("Study weak area")}</button></div><div className="mt-6 grid gap-3 md:grid-cols-2">{subject.topics.map((topic) => <TopicRow key={topic.id} topic={topic} />)}</div></div></div>; }
function StudyTab({ subject, onStart, onTab }: { subject: Subject; onStart: () => void; onTab: (tab: "chat" | "flashcards") => void }) { return <div className="mt-6 grid gap-5 md:grid-cols-3"><div className="card p-5 md:col-span-2"><div className="kicker">{trStatic("Study summary")}</div><h2 className="mt-2 text-2xl font-extrabold tracking-[-.04em]">{trStatic("The short version you can use.")}</h2><p className="mt-4 text-sm leading-7 text-[#52656a]">{subject.name} currently has {subject.materials.length} source{subject.materials.length === 1 ? "" : "s"} and {subject.topics.length} indexed topic{subject.topics.length === 1 ? "" : "s"}. Start with {subject.topics.find((topic) => topic.weak)?.name ?? "your first topic"}, then use active recall to check what stayed with you.</p><div className="mt-6 flex flex-wrap gap-2"><button className="btn-primary" onClick={onStart}><Play className="size-4" />{trStatic("Start focused session")}</button><button className="btn-light" onClick={() => onTab("flashcards")}>{trStatic("Review flashcards")}</button><button className="btn-light" onClick={() => onTab("chat")}>{trStatic("Explain something")}</button></div></div><div className="card p-5"><div className="kicker">{trStatic("Three ways to use this space")}</div><div className="mt-5 space-y-4"><div className="flex gap-3"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-[#eaf4f1] text-xs font-extrabold text-[#0f766e]">01</span><div><div className="text-sm font-extrabold">{trStatic("Understand")}</div><div className="mt-1 text-xs leading-5 text-[#879498]">{trStatic("Ask for a simpler explanation.")}</div></div></div><div className="flex gap-3"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-[#fff4df] text-xs font-extrabold text-[#b77b23]">02</span><div><div className="text-sm font-extrabold">{trStatic("Practice")}</div><div className="mt-1 text-xs leading-5 text-[#879498]">{trStatic("Turn topics into questions.")}</div></div></div><div className="flex gap-3"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-[#eef1fa] text-xs font-extrabold text-[#6270ab]">03</span><div><div className="text-sm font-extrabold">{trStatic("Review")}</div><div className="mt-1 text-xs leading-5 text-[#879498]">{trStatic("Return to what felt uncertain.")}</div></div></div></div></div></div>; }
function PracticeTab({ subject, onPractice }: { subject: Subject; onPractice: () => void }) { return <div className="mt-6 grid gap-4 md:grid-cols-2"><button className="card group p-6 text-left" onClick={onPractice}><div className="flex items-start justify-between"><div className="grid size-11 place-items-center rounded-2xl bg-[#eaf4f1] text-[#0f766e]"><ListChecks className="size-5" /></div><ArrowRight className="size-4 text-[#9ca8a7] transition group-hover:translate-x-1 group-hover:text-[#0f766e]" /></div><h2 className="mt-6 text-xl font-extrabold">{trStatic("Practice test")}</h2><p className="mt-2 text-sm leading-6 text-[#7a898b]">{trStatic("A focused set of questions from your weakest topics, with explanations and a next step.")}</p><div className="mt-5 text-xs font-extrabold text-[#0f766e]">{trStatic("10 questions · mixed recall")}</div></button><button className="card group p-6 text-left" onClick={onPractice}><div className="flex items-start justify-between"><div className="grid size-11 place-items-center rounded-2xl bg-[#fff4df] text-[#b77b23]"><GraduationCap className="size-5" /></div><ArrowRight className="size-4 text-[#9ca8a7] transition group-hover:translate-x-1 group-hover:text-[#b77b23]" /></div><h2 className="mt-6 text-xl font-extrabold">{trStatic("Full mock exam")}</h2><p className="mt-2 text-sm leading-6 text-[#7a898b]">{trStatic("Run a mixed test from all indexed topics and review your strengths and weak areas afterwards.")}</p><div className="mt-5 text-xs font-extrabold text-[#9d7a3a]">{trStatic("Built from")} {subject.topics.length} {trStatic("topics")}</div></button></div>; }
function ProgressSubject({ subject }: { subject: Subject }) { return <div className="mt-6 grid gap-5 md:grid-cols-[.8fr_1.2fr]"><div className="card p-6"><div className="kicker">{trStatic("Subject mastery")}</div><div className="mt-4 flex items-end gap-2"><div className="text-5xl font-extrabold tracking-[-.07em] text-[#0f766e]">{subject.mastery}%</div><div className="pb-2 text-xs font-bold text-[#8b9899]">{trStatic("working mastery")}</div></div><div className="progress-track mt-5"><div className="progress-fill" style={{ width: `${subject.mastery}%` }} /></div><p className="mt-4 text-sm leading-6 text-[#7c8a8d]">{trStatic("Studied content and demonstrated recall are tracked separately, so time spent is not mistaken for mastery.")}</p></div><div className="card p-6"><div className="kicker">{trStatic("Topic mastery")}</div><div className="mt-4 space-y-4">{subject.topics.map((topic) => <div key={topic.id}><div className="flex justify-between text-xs"><span className="font-extrabold text-[#40545a]">{topic.name}</span><span className="font-extrabold text-[#0f766e]">{topic.mastery}%</span></div><div className="progress-track mt-2"><div className="progress-fill" style={{ width: `${topic.mastery}%` }} /></div></div>)}</div></div></div>; }

function StudyPlan({ workspace, onNavigate }: { workspace: Workspace; onNavigate: (path: string) => void }) { const tasks = workspace.subjects.flatMap((subject) => subject.topics.filter((topic) => topic.weak).map((topic) => ({ subject, topic }))); return <><div><div className="eyebrow">{trStatic("Adaptive planning")}</div><h1 className="page-title">{trStatic("A plan that listens.")}</h1><p className="page-subtitle">{trStatic("Your plan changes as your confidence, exam dates, and real study time change.")}</p></div><div className="grid-dashboard mt-8"><div className="card p-6"><div className="flex items-center justify-between"><div><div className="kicker">{trStatic("Today’s focus")}</div><h2 className="mt-2 text-2xl font-extrabold tracking-[-.04em]">{trStatic("Make the next hour count.")}</h2></div><CalendarDays className="size-6 text-[#0f766e]" /></div><div className="mt-6 space-y-3">{tasks.length ? tasks.map(({ subject, topic }, index) => <div key={`${subject.id}-${topic.id}`} className="flex items-center gap-3 rounded-2xl border border-[#e4ece8] p-4"><div className="grid size-8 place-items-center rounded-xl bg-[#eaf4f1] text-xs font-extrabold text-[#0f766e]">0{index + 1}</div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#40525a]">{subject.name} · {topic.name}</div><div className="mt-1 text-xs text-[#869396]">{trStatic("Weak topic")} · {formatExam(subject.examDate)}</div></div><button className="btn-quiet" onClick={() => onNavigate(`/subjects/${subject.id}`)}>{trStatic("Open")}<ArrowRight className="size-4" /></button></div>) : <div className="soft-card p-5 text-sm text-[#688078]">{trStatic("Add exam dates and sources to let Study Manager shape your plan.")}</div>}</div></div><div className="card p-6"><div className="kicker">{trStatic("Planning signal")}</div><div className="mt-5 text-4xl font-extrabold tracking-[-.06em] text-[#0f766e]">42 min</div><div className="mt-1 text-xs font-semibold text-[#889597]">{trStatic("your recent average session")}</div><div className="mt-6 rounded-2xl bg-[#f0f6f3] p-4 text-xs leading-6 text-[#5b7770]">{trStatic("Your plan is becoming more realistic. It favors one focused task over filling time with low-value work.")}</div><div className="mt-6 flex items-center gap-2 text-xs font-bold text-[#6f8380]"><CircleCheck className="size-4 text-[#0f766e]" />{trStatic("Exam-aware priorities enabled")}</div></div></div></>; }

function Review({ workspace, setWorkspace, onNavigate }: { workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void }) { const queue = workspace.subjects.flatMap((subject) => subject.topics.filter((topic) => topic.weak).map((topic) => ({ subject, topic }))); const [done, setDone] = useState<string[]>([]); return <><div><div className="eyebrow">{trStatic("Spaced review")}</div><h1 className="page-title">{trStatic("Review me.")}</h1><p className="page-subtitle">{trStatic("Return to the things that were hard, uncertain, or worth saving — before they fade.")}</p></div><div className="mt-8 grid gap-5 lg:grid-cols-[1fr_.7fr]"><div className="card p-6"><div className="flex items-center justify-between"><div><div className="kicker">{trStatic("Priority queue")}</div><h2 className="mt-2 text-xl font-extrabold">{Math.max(0, queue.length - done.length)} {trStatic("reviews waiting")}</h2></div><RotateCcw className="size-5 text-[#0f766e]" /></div><div className="mt-5 space-y-3">{queue.map(({ subject, topic }) => { const id = `${subject.id}-${topic.id}`; const complete = done.includes(id); return <div key={id} className={`rounded-2xl border p-4 ${complete ? "border-[#d8e9df] bg-[#f5fbf7]" : "border-[#e4ece8]"}`}><div className="flex items-start gap-3"><div className="grid size-9 place-items-center rounded-xl bg-[#fff3df] text-[#b97e26]"><Lightbulb className="size-4" /></div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#3f5158]">{subject.name} · {topic.name}</div><div className="mt-1 text-xs leading-5 text-[#849294]">{topic.note}</div><div className="mt-2 text-[10px] font-bold text-[#99a5a6]">{trStatic("Review priority")} · {100 - topic.mastery}%</div></div><button className={complete ? "btn-quiet" : "btn-light"} onClick={() => setDone((prev) => prev.includes(id) ? prev.filter((value) => value !== id) : [...prev, id])}>{complete ? <><Check className="size-4" />{trStatic("Reviewed")}</> : <><Play className="size-4 text-[#0f766e]" />{trStatic("Review")}</>}</button></div></div>; })}</div></div><div className="card p-6"><div className="kicker">{trStatic("Why this queue?")}</div><h2 className="mt-2 text-xl font-extrabold">{trStatic("Confidence is part of mastery.")}</h2><p className="mt-3 text-sm leading-6 text-[#7b8a8c]">{trStatic("A correct answer with low confidence still returns here. A repeated mistake rises in priority until it becomes reliable recall.")}</p><div className="mt-6 flex items-center gap-3 rounded-2xl bg-[#eaf4f1] p-4"><div className="grid size-9 place-items-center rounded-xl bg-white text-[#0f766e]"><Target className="size-4" /></div><div><div className="text-xs font-extrabold text-[#3c605a]">{trStatic("Simple spaced review")}</div><div className="mt-1 text-[11px] text-[#6f8984]">{trStatic("No noisy gamification. Just the next useful return.")}</div></div></div></div></div></>; }

function ProgressView({ workspace }: { workspace: Workspace }) { const average = Math.round(workspace.subjects.reduce((sum, item) => sum + item.mastery, 0) / Math.max(1, workspace.subjects.length)); return <><div><div className="eyebrow">{trStatic("Evidence of progress")}</div><h1 className="page-title">{trStatic("See what is sticking.")}</h1><p className="page-subtitle">{trStatic("Time studied is useful. Demonstrated mastery tells the fuller story.")}</p></div><div className="grid-metrics mt-8"><Metric icon={<BarChart3 />} label="Overall mastery" value={`${average}%`} note="Across your spaces" /><Metric icon={<Timer />} label="Study time" value={`${workspace.subjects.reduce((sum, item) => sum + item.minutes, 0)} min`} note="Logged in sessions" /><Metric icon={<Zap />} label="Current streak" value={`${workspace.streak} days`} note="Personal consistency" /><Metric icon={<CircleCheck />} label="Saved for review" value={`${workspace.savedItems.length}`} note="Your evidence bank" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_.8fr]"><div className="card p-6"><div className="kicker">{trStatic("Subject mastery")}</div><div className="mt-5 space-y-5">{workspace.subjects.map((subject) => <div key={subject.id}><div className="flex justify-between text-sm"><span className="font-extrabold">{subject.name}</span><span className="font-extrabold text-[#0f766e]">{subject.mastery}%</span></div><div className="progress-track mt-2"><div className="progress-fill" style={{ width: `${subject.mastery}%`, background: subject.color }} /></div><div className="mt-2 text-[11px] font-semibold text-[#8b989a]">{subject.topics.filter((topic) => topic.weak).length} weak topic{subject.topics.filter((topic) => topic.weak).length === 1 ? "" : "s"} · {subject.minutes} min studied</div></div>)}</div></div><div className="card p-6"><div className="kicker">{trStatic("Your pattern")}</div><h2 className="mt-2 text-xl font-extrabold">{trStatic("You do better with a clear finish line.")}</h2><p className="mt-3 text-sm leading-6 text-[#7c8b8d]">{trStatic("Your recent sessions are short and consistent. StudyNivo will keep recommending focused 30–45 minute blocks instead of stretching the plan to an unrealistic two hours.")}</p><div className="mt-5 rounded-2xl bg-[#f0f6f3] p-4"><div className="flex items-center gap-2 text-xs font-extrabold text-[#3d665e]"><Sparkles className="size-4 text-[#0f766e]" />{trStatic("Personal insight")}</div><div className="mt-2 text-xs leading-5 text-[#66817b]">{trStatic("Mastery grows fastest when practice follows explanation.")}</div></div></div></div></>; }

function SavedItems({ workspace, setWorkspace }: { workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>> }) { return <><div><div className="eyebrow">{trStatic("Evidence bank")}</div><h1 className="page-title">{trStatic("Saved items.")}</h1><p className="page-subtitle">{trStatic("Keep the details you want StudyNivo to bring back into a future review.")}</p></div><div className="mt-8 grid gap-3">{workspace.savedItems.length ? workspace.savedItems.map((item) => <div key={item.id} className="card flex items-start gap-4 p-5"><div className="grid size-10 place-items-center rounded-xl bg-[#eaf4f1] text-[#0f766e]"><BookMarked className="size-5" /></div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold text-[#3e5157]">{item.title}</div><div className="mt-2 flex flex-wrap gap-2"><span className="topic-chip">{item.subject}</span><span className="source-pill">{item.source}</span></div></div><button className="btn-quiet" onClick={() => setWorkspace((prev) => ({ ...prev, savedItems: prev.savedItems.filter((saved) => saved.id !== item.id) }))}>{trStatic("Remove")}</button></div>) : <div className="card p-8 text-center"><BookMarked className="mx-auto size-7 text-[#95a3a3]" /><div className="mt-4 text-sm font-extrabold">{trStatic("Nothing saved yet.")}</div><div className="mt-2 text-xs text-[#8a9899]">{trStatic("Bookmark a useful explanation or source passage inside a subject space.")}</div></div>}</div></>; }

function Settings({ locale, onLocale }: { locale: Locale; onLocale: (locale: Locale) => void }) { return <><div><div className="eyebrow">{trStatic("Workspace preferences")}</div><h1 className="page-title">{trStatic("Settings.")}</h1><p className="page-subtitle">{trStatic("Make StudyNivo feel natural to the way you study.")}</p></div><div className="mt-8 grid max-w-3xl gap-4"><div className="card p-6"><div className="flex items-start gap-4"><div className="grid size-10 place-items-center rounded-xl bg-[#eaf4f1] text-[#0f766e]"><Languages className="size-5" /></div><div className="flex-1"><div className="text-sm font-extrabold">{trStatic("Interface language")}</div><div className="mt-1 text-xs leading-5 text-[#879497]">{trStatic("Your material language stays independent. Only the interface changes.")}</div><div className="mt-4"><LocalePicker locale={locale} onChange={onLocale} /></div></div></div></div><div className="card p-6"><div className="flex items-start gap-4"><div className="grid size-10 place-items-center rounded-xl bg-[#fff4df] text-[#bb7d25]"><Clock3 className="size-5" /></div><div><div className="text-sm font-extrabold">{trStatic("Study rhythm")}</div><div className="mt-1 text-xs leading-5 text-[#879497]">{trStatic("Study Manager uses your actual session history to keep recommendations realistic.")}</div><div className="mt-4 flex flex-wrap gap-2"><span className="topic-chip">{trStatic("Daily goal · 60 min")}</span><span className="topic-chip">{trStatic("Short sessions favored")}</span></div></div></div></div><div className="card p-6"><div className="flex items-start gap-4"><div className="grid size-10 place-items-center rounded-xl bg-[#eef1fa] text-[#6572aa]"><ShieldCheckIcon /></div><div><div className="text-sm font-extrabold">{trStatic("Privacy boundary")}</div><div className="mt-1 max-w-xl text-xs leading-5 text-[#879497]">{trStatic("Each subject is an isolated study space. StudyNivo does not mix your sources or expose them across accounts.")}</div></div></div></div><div className="card p-6"><div className="flex items-center justify-between gap-4"><div><div className="text-sm font-extrabold">{trStatic("Your review shelf")}</div><div className="mt-1 text-xs leading-5 text-[#879497]">{trStatic("Saved explanations and source-linked reminders live here.")}</div></div><a className="btn-light" href="/saved">{trStatic("Open saved items")}<ArrowRight className="size-4" /></a></div></div></div></>; }

function StudySession({ sessionId, workspace, setWorkspace, onNavigate }: { sessionId: string; workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void }) { const session = workspace.session?.id === sessionId ? workspace.session : undefined; const subject = workspace.subjects.find((item) => item.id === session?.subjectId); const topic = subject?.topics.find((item) => item.id === session?.topicId); const [elapsed, setElapsed] = useState(session?.elapsed ?? 0); const [paused, setPaused] = useState(session?.status === "paused"); useEffect(() => { if (!session || paused) return; const id = window.setInterval(() => setElapsed((value) => Math.min(session.duration * 60, value + 1)), 1000); return () => window.clearInterval(id); }, [session, paused]); if (!session || !subject || !topic) return <div className="card p-8 text-center"><CircleAlert className="mx-auto size-7 text-[#b9802c]" /><div className="mt-3 text-sm font-extrabold">{trStatic("This session is no longer available.")}</div><button className="btn-primary mt-5" onClick={() => onNavigate("/dashboard")}>{trStatic("Back to dashboard")}</button></div>; const finish = () => { setWorkspace((prev) => ({ ...prev, minutesToday: prev.minutesToday + Math.max(1, Math.round(elapsed / 60)), subjects: prev.subjects.map((item) => item.id === subject.id ? { ...item, minutes: item.minutes + Math.max(1, Math.round(elapsed / 60)) } : item), session: undefined })); onNavigate("/dashboard"); }; const pause = () => { setPaused((value) => !value); setWorkspace((prev) => prev.session ? { ...prev, session: { ...prev.session, elapsed, status: paused ? "active" : "paused" } } : prev); }; return <div className="mx-auto max-w-3xl"><button className="btn-quiet -ml-2 mb-5" onClick={() => onNavigate("/dashboard")}><ArrowRight className="size-4 rotate-180" />{trStatic("Exit session")}</button><div className="card overflow-hidden"><div className="bg-[#0f766e] p-7 text-white"><div className="flex items-center justify-between"><div><div className="text-xs font-bold text-[#bde8df]">{trStatic("Focused study session")}</div><h1 className="mt-2 text-3xl font-extrabold tracking-[-.05em]">{subject.name} · {topic.name}</h1></div><div className="grid size-12 place-items-center rounded-2xl bg-white/10"><Timer className="size-6" /></div></div><div className="mt-7 flex items-end justify-between"><div><div className="text-5xl font-extrabold tracking-[-.07em]">{String(Math.floor(elapsed / 60)).padStart(2, "0")}:{String(elapsed % 60).padStart(2, "0")}</div><div className="mt-1 text-xs text-[#c8e8e2]">{trStatic("of")} {session.duration}:00 {trStatic("planned")}</div></div><div className="w-32"><div className="mb-2 text-right text-xs font-extrabold text-[#c8e8e2]">{Math.round((elapsed / (session.duration * 60)) * 100)}%</div><div className="h-2 rounded-full bg-white/20"><div className="h-2 rounded-full bg-white" style={{ width: `${Math.min(100, (elapsed / (session.duration * 60)) * 100)}%` }} /></div></div></div></div><div className="p-7"><div className="kicker">{trStatic("Session brief")}</div><h2 className="mt-2 text-2xl font-extrabold">{trStatic("Rebuild the idea, then test it.")}</h2><p className="mt-3 text-sm leading-7 text-[#708084]">{trStatic("Spend the first part reviewing the source-linked explanation for")} {topic.name}. {trStatic("Finish by answering one question without looking back.")}</p><div className="mt-6 grid gap-3 sm:grid-cols-3"><div className="soft-card p-4"><div className="text-xs font-extrabold text-[#3b5556]">1 · {trStatic("Understand")}</div><div className="mt-2 text-[11px] leading-5 text-[#7e8e8f]">{trStatic("Read the focused explanation.")}</div></div><div className="soft-card p-4"><div className="text-xs font-extrabold text-[#3b5556]">2 · {trStatic("Recall")}</div><div className="mt-2 text-[11px] leading-5 text-[#7e8e8f]">{trStatic("Explain it in your own words.")}</div></div><div className="soft-card p-4"><div className="text-xs font-extrabold text-[#3b5556]">3 · {trStatic("Reflect")}</div><div className="mt-2 text-[11px] leading-5 text-[#7e8e8f]">{trStatic("Mark confidence before you leave.")}</div></div></div><div className="mt-7 flex flex-wrap gap-3"><button className="btn-primary" onClick={pause}>{paused ? <><Play className="size-4" />{trStatic("Resume")}</> : <><Pause className="size-4" />{trStatic("Pause session")}</>}</button><button className="btn-light" onClick={finish}><Check className="size-4 text-[#0f766e]" />{trStatic("Complete session")}</button></div><div className="mt-5 flex items-center gap-2 text-xs font-semibold text-[#8a9798]"><CircleCheck className="size-4 text-[#0f766e]" />{trStatic("Your progress is saved when you pause or complete.")}</div></div></div></div>; }

function PracticeTest({ subjectId, workspace, setWorkspace, onNavigate }: { subjectId: string; workspace: Workspace; setWorkspace: React.Dispatch<React.SetStateAction<Workspace>>; onNavigate: (path: string) => void }) { const subject = workspace.subjects.find((item) => item.id === subjectId); const [index, setIndex] = useState(0); const [selected, setSelected] = useState<string | null>(null); const [confidence, setConfidence] = useState<string | null>(null); const [finished, setFinished] = useState(false); const questions = subject?.topics.map((topic) => ({ topic, prompt: `Which study move best strengthens ${topic.name}?`, options: ["Read the summary once", "Explain it and answer a new question", "Skip it until exam week"], answer: "Explain it and answer a new question" })) ?? []; const question = questions[index % Math.max(1, questions.length)]; if (!subject || !question) return null; if (finished) return <div className="mx-auto max-w-3xl"><div className="card p-7"><div className="eyebrow">{trStatic("Practice report")}</div><h1 className="page-title">{trStatic("Good work showing your gaps.")}</h1><div className="mt-7 grid gap-3 sm:grid-cols-3"><Metric icon={<Target />} label="Score" value={selected ? "100%" : "0%"} note="One focused question" /><Metric icon={<Brain />} label="Strong topic" value={question.topic.name} note="Keep it warm" /><Metric icon={<Lightbulb />} label="Next step" value="Review" note="Low confidence matters" /></div><div className="mt-6 rounded-2xl bg-[#f1f7f4] p-5 text-sm leading-7 text-[#53736b]">{trStatic("Your answer is connected to")}<b>{question.topic.source}</b>. Return to this topic later if your confidence was low — a correct answer is not the same as reliable recall.</div><button className="btn-primary mt-6" onClick={() => onNavigate(`/subjects/${subject.id}`)}>{trStatic("Back to")} {subject.name}</button></div></div>; const choose = (value: string) => setSelected(value); const next = () => { if (!selected) return; if (index + 1 >= questions.length) setFinished(true); else { setIndex((value) => value + 1); setSelected(null); setConfidence(null); } }; return <div className="mx-auto max-w-3xl"><button className="btn-quiet -ml-2 mb-5" onClick={() => onNavigate(`/subjects/${subject.id}`)}><ArrowRight className="size-4 rotate-180" />{trStatic("Exit test")}</button><div className="card p-7"><div className="flex items-center justify-between"><div><div className="eyebrow">{trStatic("Practice test ·")} {subject.name}</div><h1 className="mt-2 text-2xl font-extrabold tracking-[-.04em]">{trStatic("Question")} {index + 1} {trStatic("of")} {questions.length}</h1></div><span className="topic-chip">{question.topic.name}</span></div><div className="progress-track mt-5"><div className="progress-fill" style={{ width: `${((index + 1) / questions.length) * 100}%` }} /></div><h2 className="mt-9 text-2xl font-extrabold leading-tight tracking-[-.04em]">{question.prompt}</h2><div className="mt-6 grid gap-3">{question.options.map((option) => <button key={option} className={`rounded-2xl border p-4 text-left text-sm font-bold transition ${selected === option ? "border-[#5db9ae] bg-[#eaf4f1] text-[#0f766e]" : "border-[#e3ebe7] text-[#52656a] hover:border-[#acd1c8]"}`} onClick={() => choose(option)}>{selected === option ? <Check className="mr-2 inline size-4" /> : <span className="mr-2 inline-block size-4 rounded-full border border-[#cbd8d4] align-[-2px]" />}{option}</button>)}</div><div className="mt-8 border-t border-[#e5ece8] pt-6"><div className="text-xs font-extrabold text-[#506268]">{trStatic("How confident are you?")}</div><div className="mt-3 flex flex-wrap gap-2">{["Low", "Medium", "High"].map((value) => <button key={value} className={`btn-light ${confidence === value ? "border-[#75b8aa] bg-[#eef8f4] text-[#0f766e]" : ""}`} onClick={() => setConfidence(value)}>{value}</button>)}</div></div><button className="btn-primary mt-7 w-full" disabled={!selected || !confidence} onClick={next}>{index + 1 >= questions.length ? trStatic("See results") : trStatic("Next question")} <ArrowRight className="size-4" /></button></div></div>; }

function NotFoundView({ onNavigate }: { onNavigate: (path: string) => void }) { return <div className="mx-auto max-w-xl py-16 text-center"><div className="mx-auto grid size-14 place-items-center rounded-2xl bg-[#eaf4f1] text-[#0f766e]"><Search className="size-6" /></div><div className="eyebrow mt-6">{trStatic("Page not found")}</div><h1 className="mt-2 text-3xl font-extrabold tracking-[-.05em]">{trStatic("That study path does not exist.")}</h1><p className="mt-3 text-sm leading-6 text-[#7a898b]">{trStatic("The route may be old or the subject may no longer be in your workspace.")}</p><button className="btn-primary mt-6" onClick={() => onNavigate("/dashboard")}>{trStatic("Back to dashboard")}<ArrowRight className="size-4" /></button></div>; }

function AuthGate() { const login = () => { try { startLogin(); } catch (error) { console.error(error); } }; return <div className="landing-shell grid min-h-screen place-items-center"><div className="auth-card card text-center"><div className="mx-auto w-fit"><Logo /></div><div className="mt-8 grid size-14 place-items-center rounded-2xl bg-[#eaf4f1] text-[#0f766e]"><GraduationCap className="size-7" /></div><h1 className="mt-5 text-2xl font-extrabold tracking-[-.04em]">{trStatic("Your study space is private.")}</h1><p className="mt-3 text-sm leading-6 text-[#77868a]">{trStatic("Sign in to access your subjects, materials, progress, and personalized next step.")}</p><button className="btn-primary mt-7 w-full" onClick={login}>{trStatic("Continue with Manus account")}<ArrowRight className="size-4" /></button><p className="mt-4 text-[11px] leading-5 text-[#9aa5a5]">{trStatic("Google and email provider options appear when they are configured for this project.")}</p></div></div>; }

export default function App() {
  const { user, loading, logout } = useAuth();
  const [locale, setLocale] = useState<Locale>(() => (localStorage.getItem("studynivo-locale") as Locale) || "en");
  setActiveLocale(locale);
  const [location] = useLocation();
  const [workspace, setWorkspace] = useWorkspace(user?.openId);
  useEffect(() => { localStorage.setItem("studynivo-locale", locale); document.documentElement.lang = locale; document.documentElement.dir = getDirection(locale); }, [locale]);
  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f8f8f5]"><div className="text-center"><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-[#eaf4f1] text-[#0f766e]"><Sparkles className="size-5 animate-pulse" /></div><div className="mt-4 text-sm font-extrabold text-[#45575c]">{trStatic("Preparing your study space…")}</div></div></div>;
  if (!user && location === "/") return <Landing locale={locale} onLocale={setLocale} />;
  if (!user) return <AuthGate />;
  return <AppShell locale={locale} onLocale={setLocale} workspace={workspace} setWorkspace={setWorkspace} user={user} logout={logout} />;
}
